int fd = 3;
off_t offset = 0;
off_t len_bytes = 1024 * 1024; // 1 MB region

// Standard wrapper for fadvise64() syscall
int result;

// 1. Optimize for sequential access over the region
result = posix_fadvise(fd, offset, len_bytes,
                       POSIX_FADV_SEQUENTIAL);

// 2. Pre-fetch data into the cache (non-blocking)
posix_fadvise(fd, offset, len_bytes,
              POSIX_FADV_WILLNEED);

// 3. Discard cached pages (advice for the kernel)
posix_fadvise(fd, offset, len_bytes,
              POSIX_FADV_DONTNEED);

// 4. Advise from offset until EOF (len = 0)
posix_fadvise(fd, offset, 0,
              POSIX_FADV_RANDOM);
